# Detect labels or objects in a static image using Clarifai\nimport os\n\n# Clarifai SDK for image label detection\nfrom clarifai.rest import Clarifi\n\nclass DetectImageLabels:\n    \"\"\"Detect labels/objects in a static image.\n    • Provider: Clarifai Image Recognition (sdk=clarifai, interface=sdk, auth=CLARIFAI_PAT)\n    \"\"\"\n    @staticmethod\n    def detect(image_path):\n        \"\"\"Run label detection on the given image file.\n        Args:\n            image_path (str): Path to the local image file.\n        Returns:\n            list: Detected concepts with name and probability.\n        \"\"\"\n        client = VisionClient.get_clarifai_client()\n        model = client.public_models.general_image_model  # default model\n        response = model.predict_by_filename(image_path)\n        # Extract concepts\n        concepts = [(c['name'], c['value']) for c in response['outputs'][0]['data']['concepts']]\n        return concepts\n\n# Local helper utilities (loaded in VisionClient)\n# -----------------------------------------------------------------------------\n# Configuration loading and client helpers defined in vision_client.py (separate file)\n# -----------------------------------------------------------------------------\n
